import { useState, type FormEvent } from 'react';
import { JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

export type ProfileLanguage = 'ru' | 'en';

export interface ProfileSettings {
  name: string;
  language: ProfileLanguage;
  emailNotifications: boolean;
}

export interface ProfileSettingsFormProps {
  initialSettings?: ProfileSettings;
  onSave: (settings: ProfileSettings) => void;
}

const LANGUAGE_OPTIONS = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

function ProfileSettingsForm({ initialSettings, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<ProfileLanguage>(initialSettings?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? false,
  );
  const [submitted, setSubmitted] = useState(false);

  const trimmedName = name.trim();
  const nameError = submitted && trimmedName.length === 0 ? 'Укажите имя' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSubmitted(true);
    if (trimmedName.length === 0) return;
    onSave({ name: trimmedName, language, emailNotifications });
  };

  return (
    <form
      onSubmit={submit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 20,
        padding: 24,
        maxWidth: 420,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <h2
        style={{
          margin: 0,
          fontFamily: 'var(--jx-font-display)',
          color: 'var(--jx-text)',
        }}
      >
        Настройки профиля
      </h2>

      <JxInputField
        label="Имя"
        name="name"
        required
        value={name}
        onChange={(event) => setName(event.target.value)}
        errorText={nameError}
        helperText="Так вас увидят другие участники"
        placeholder="Например, Анна Смирнова"
      />

      <JxSelect
        label="Язык интерфейса"
        options={LANGUAGE_OPTIONS}
        value={language}
        onValueChange={(value) => setLanguage(value as ProfileLanguage)}
        placeholder="Выберите язык"
      />

      <JxSwitch
        label="Уведомления на почту"
        name="emailNotifications"
        checked={emailNotifications}
        onChange={(event) => setEmailNotifications(event.target.checked)}
      />

      <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
        <JxButton type="submit" variant="primary">
          Сохранить
        </JxButton>
      </div>
    </form>
  );
}

export default ProfileSettingsForm;

